def filtrer_par_budget(offres, budget_min=None):
    """Retient les offres dont le TJM analysé atteint le budget minimum.

    Règle métier validée avec le PO :
      - la borne est inclusive (une offre à 600 passe un budget de 600) ;
      - une offre sans budget renseigné est exclue dès qu'un budget est demandé :
        on ne suppose jamais un budget absent, on l'écarte ;
      - un budget absent (None) ne filtre rien ; un budget à 0 demande simplement
        que le budget soit renseigné ;
      - l'ordre d'entrée est conservé : le tri est la responsabilité de trier().
    """
    if not offres:
        return []
    if budget_min is None:
        return list(offres)
    retenues = []
    for offre in offres:
        if not isinstance(offre, dict):
            continue
        tjm = analyze_tjm(offre).get("tjm")

def api_jobs():
    filters = {}
    if request.args.get("qa"):
        filters["qa_only"] = request.args.get("qa") == "1"
    if request.args.get("unapplied"):
        filters["not_applied"] = request.args.get("unapplied") == "1"
    if request.args.get("search"):
        filters["search"] = request.args.get("search")
    if request.args.get("source"):
        filters["source"] = request.args.get("source")

    jobs = get_jobs(filters)

    # Filtre par budget minimum : le TJM est analysé depuis le champ libre « salary »,
    # il ne peut pas être exprimé en SQL — on filtre donc après lecture, via la
    # fonction testée unitairement (matcher.filtrer_par_budget).
    budget_min = request.args.get("budget_min", type=int)
    if budget_min is not None:
        jobs = filtrer_par_budget(jobs, budget_min)

    return jsonify(jobs)

class TestFiltreBudget:
    def test_borne_inclusive_au_seuil(self):
        """Une offre exactement au budget minimum doit être retenue."""
        retenues = filtrer_par_budget([_offre("Offre 600 pile", "600 €/jour")], 600)
        assert [o["title"] for o in retenues] == ["Offre 600 pile"]

    def test_moyenne_de_plage_utilisee_comme_tjm(self):
        """« 600-700 €/jour » est analysé à 650 : retenue à 600, exclue à 700."""
        assert filtrer_par_budget([_offre("Plage", "600-700 €/jour")], 600) != []
        assert filtrer_par_budget([_offre("Plage", "600-700 €/jour")], 700) == []

    def test_offres_sans_budget_exclues(self):
        retenues = filtrer_par_budget(OFFRES, 500)
        titres = [o["title"] for o in retenues]
        assert "Offre sans budget" not in titres
        assert "Offre budget illisible" not in titres

    def test_budget_absent_ne_filtre_rien(self):
        assert len(filtrer_par_budget(OFFRES, None)) == len(OFFRES)

    def test_budget_zero_conserve_toutes_les_offres_chiffrees(self):
        titres = [o["title"] for o in filtrer_par_budget(OFFRES, 0)]
        assert titres == ["Offre 900", "Offre 600", "Offre 520"]

    def test_ordre_d_entree_conserve(self):
        titres = [o["title"] for o in filtrer_par_budget(OFFRES, 500)]

